PRAGMA foreign_keys = ON;
CREATE TABLE users (id INTEGER PRIMARY KEY AUTOINCREMENT, full_name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, trust_score INTEGER NOT NULL DEFAULT 70 CHECK(trust_score BETWEEN 0 AND 100), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE wallets (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER UNIQUE NOT NULL, balance REAL NOT NULL DEFAULT 0 CHECK(balance >= 0), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE loans (id INTEGER PRIMARY KEY AUTOINCREMENT, borrower_id INTEGER NOT NULL, loan_type TEXT NOT NULL, amount REAL NOT NULL CHECK(amount > 0), funded_amount REAL NOT NULL DEFAULT 0 CHECK(funded_amount >= 0), term_months INTEGER NOT NULL CHECK(term_months > 0), description TEXT, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','funding','funded','active','repaid','rejected','defaulted')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(borrower_id) REFERENCES users(id));
CREATE TABLE contributions (id INTEGER PRIMARY KEY AUTOINCREMENT, loan_id INTEGER NOT NULL, lender_id INTEGER NOT NULL, amount REAL NOT NULL CHECK(amount > 0), lender_return_rate REAL NOT NULL DEFAULT 0.12, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(loan_id) REFERENCES loans(id), FOREIGN KEY(lender_id) REFERENCES users(id));
CREATE TABLE transactions (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, loan_id INTEGER, transaction_type TEXT NOT NULL CHECK(transaction_type IN ('deposit','withdrawal','funding','disbursement','repayment','return','fee')), amount REAL NOT NULL CHECK(amount > 0), reference TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(loan_id) REFERENCES loans(id));
CREATE TABLE repayments (id INTEGER PRIMARY KEY AUTOINCREMENT, loan_id INTEGER NOT NULL, amount REAL NOT NULL CHECK(amount > 0), due_date TEXT, paid_at TEXT, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','paid','late')), FOREIGN KEY(loan_id) REFERENCES loans(id));
CREATE INDEX idx_loans_status ON loans(status);
CREATE INDEX idx_contributions_loan ON contributions(loan_id);
CREATE INDEX idx_transactions_user ON transactions(user_id);
